from pathlib import Path
import json,html,datetime
from collections import Counter
P=Path('/home/robot/research/projects/wm_symbolic');R=P/'runs/core1200_v1';B=P/'data/core1200_v1'
def link(path,text):return f'<a href="../{path}">{text}</a>'
def main():
 m=json.loads((B/'data_manifest.json').read_text());n=len(m['records']);counts=Counter(x['split'] for x in m['records']);qa=json.loads((R/'first132_qa.json').read_text());storage=json.loads((R/'storage_first50.json').read_text());rows=[]
 for label,value,why in [('已提交真实转移',n,'每条对应一次实际技能请求；失败和零动作拒绝也保留。'),('训练 / 开发 / 测试',f"{counts['train']} / {counts['dev']} / {counts['test']}",'固定目标为720 / 240 / 240；同根三个分支不得跨集合。'),('首132条：执行器成功 / 拒绝 / 失败','108 / 22 / 2','这是执行器结果分布，不是世界模型预测准确率。'),('零动作拒绝端态不变','22 / 22','观察、真实位置和标签保持一致，避免把请求误标成效果。'),('同根分支复位最大差异','0','实际机器人与场景数组均比较；持物起点通过真实动作重放建立。'),('首50条原始记录',f"{storage['bytes']/1e6:.1f} MB",'含双相机视频、动作、历史帧和私有物理轨迹；不含DINO缓存。'),('预计1200条原始记录',f"{storage['projected1200_bytes']/1e9:.2f} GB",'从首50条线性估计；以最终实际占用为准。')]:rows.append(f'<tr><th>{label}</th><td>{value}</td><td>{why}</td></tr>')
 model='尚未完成独立模型评价。'
 for mode in ['probe_ownership_v2','main']:
  file=R/f'training_{mode}/result.json'
  if file.exists():
   x=json.loads(file.read_text());metrics=x['final_metrics'];model+=f'<p>{mode}已完成{x["updates"]}次更新；当前事实准确率{metrics["current_accuracy"]:.3f}，单步变化事实准确率{metrics["prior_changed_accuracy"]:.3f}。'+('这是128条训练样本内检查，不代表泛化。' if mode.startswith('probe') else '主模型选择只使用C开发集，D测试另行冻结后一次评价。')+'</p>'
 body=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>六技能核心实验｜本机进展</title><style>body{{font:16px/1.6 system-ui,sans-serif;max-width:1180px;margin:40px auto;color:#18324b;background:#f7f9fc;padding:0 24px}}h1{{font-size:30px}}table{{border-collapse:collapse;width:100%;background:white}}td,th{{padding:12px;border-bottom:1px solid #dbe3ec;text-align:left}}th{{width:26%}}img{{max-width:100%;background:white}}.note{{padding:16px;background:#e7eff8}}a{{color:#135ca8}}small{{color:#5e7185}}</style><h1>六技能世界模型：首批真实样本已通过质量检查</h1><p>本机独立实验，使用已选定的v1物理执行器。旧HULC数据、模型和暂停状态保留；这里的1200条是用户新增授权的核心验证范围，并不等于原6000条完整方案已经完成。</p><table><thead><tr><th>检查项</th><th>实际结果</th><th>元素与原因</th></tr></thead><tbody>{''.join(rows)}</tbody></table><h2>如何保证不同任务需要不同决策</h2><p>100个根初态由50个“抽屉关闭、空手”、30个“抽屉打开、空手”和20个“抽屉打开、持物”组成；每根三个四步分支。所有分支共用根级划分：A/B训练60根，C开发20根，D测试20根。C前12根用于选模型，后8根用于校准诊断。训练与开发/测试的连续两物体组合方向不同；控制器开发及历史320份根记录均用于近重复排除。</p><p>模型只看双相机过去/当前图像、可见掩码、机器人观测和请求的技能。真实物体位置、接触、成功或拒绝原因仅进入离线标签和评分，不能作为预测或规划输入。</p><h2>双相机真实样本</h2><img src="../runs/core1200_v1/first132_qa_contact_sheet.png" alt="12组实际双相机技能开始帧"><p>每格左图为静态相机，右图为夹爪相机；标题标出根、分支、步骤和请求技能。物块原有红、蓝、粉颜色用于识别对象，没有额外热力颜色。顺序沿行阅读，可见开抽屉、抓取、放置和持物时拒绝关闭的实际场景。</p><h2>训练与接下来要证明的内容</h2><p>{model}</p><p>完成数据后从随机初始化训练新世界模型；分别评价当前状态识别、1–4步动作后果、保持原状态和错误动作对照，再用变化的初态与目标测试学习转移驱动的闭环规划。若变化预测不足，定位首个有影响的错误，不用连续拒绝或重复脚本掩盖问题。</p><p class="note">两次控制器原始失败记录保留。检查证实其中的堆叠状态经“上层物块→下层物块→抽屉”受力链归属抽屉，已修正离线位置标签并保留旧版；没有修改控制器或原始成功位。修正前探针仅保留为历史流程记录，不引用为最终标签的验证。测试环境D尚不参与模型选择。</p><p>{link('runs/core1200_v1/protocol.json','完整冻结协议')} · {link('runs/core1200_v1/first132_qa.json','132条质量审计')} · {link('runs/core1200_v1/storage_first50.json','50条存储测量')} · {link('data/core1200_v1/roots_manifest.json','100根初态及分支')} · {link('runs/core1200_v1/progress.json','最新采集进度')}</p><small>生成时间：{datetime.datetime.now(datetime.timezone.utc).isoformat()}。图像全部来源于真实模拟执行，无合成轨迹。</small></html>'''
 (P/'reports/core1200_progress.html').write_text(body)
 h=json.loads((P/'runs/continuation_handoff.json').read_text());h.update(latest_report='reports/core1200_progress.html',actual_core_transitions=n,core_qa='runs/core1200_v1/first132_qa.json');(P/'runs/continuation_handoff.json').write_text(json.dumps(h,indent=2))
 print('REPORT',P/'reports/core1200_progress.html')
if __name__=='__main__':main()
